#### Phase 1: Workflow Engine Integration

1. **Install Elsa Workflows**:
   ```bash
   dotnet add package Elsa
   dotnet add package Elsa.Persistence.EntityFramework
   dotnet add package Elsa.Activities.Http
   dotnet add package Elsa.Activities.Temporal
   dotnet add package Elsa.Activities.Email
   ```

2. **Configure Workflow Services**:
   ```csharp
   public class Startup
   {
       public void ConfigureServices(IServiceCollection services)
       {
           services
               .AddElsa(elsa => elsa
                   .UseEntityFrameworkPersistence(ef =>
                       ef.UseSqlServer(Configuration.GetConnectionString("Elsa")))
                   .AddConsoleActivities()
                   .AddHttpActivities()
                   .AddEmailActivities()
                   .AddTimerActivities()
                   .AddWorkflow<TexasProviderEnrollmentWorkflow>()
               );
       }
   }
   ```

3. **Create Workflow Base Extension Class**:
   ```csharp
   public abstract class WorkflowExtensionBase
   {
       protected readonly IWorkflowInvoker _workflowInvoker;
       protected readonly IWorkflowRegistry _workflowRegistry;

       protected WorkflowExtensionBase(
           IWorkflowInvoker workflowInvoker,
           IWorkflowRegistry workflowRegistry)
       {
           _workflowInvoker = workflowInvoker;
           _workflowRegistry = workflowRegistry;
       }

       protected async Task<WorkflowExecutionResult> ExecuteWorkflowAsync<TWorkflow>(
           object input,
           string tenantId)
           where TWorkflow : IWorkflow
       {
           var workflow = await _workflowRegistry.GetWorkflowAsync<TWorkflow>();
           var context = new WorkflowExecutionContext
           {
               Input = input,
               TenantId = tenantId
           };
           return await _workflowInvoker.InvokeAsync(workflow, context);
       }
   }
   ```

4. **Setup Workflow State Persistence**:
   ```csharp
   public class WorkflowStatePersistence
   {
       private readonly ElsaDbContext _dbContext;

       public async Task PersistWorkflowAsync(WorkflowInstance instance)
       {
           _dbContext.WorkflowInstances.Add(instance);
           await _dbContext.SaveChangesAsync();
       }

       public async Task<WorkflowInstance> LoadWorkflowAsync(string workflowInstanceId)
       {
           return await _dbContext.WorkflowInstances
               .Include(w => w.ActivityData)
               .FirstOrDefaultAsync(w => w.Id == workflowInstanceId);
       }
   }
   ```

