#### Phase 2: Custom Activity Development

5. **Create Custom Activity Template**:
   ```csharp
   public abstract class StateSpecificActivity : Activity
   {
       protected ITenantContext TenantContext { get; }
       protected ILogger Logger { get; }

       protected StateSpecificActivity(
           ITenantContext tenantContext,
           ILogger logger)
       {
           TenantContext = tenantContext;
           Logger = logger;
       }

       protected override async Task<ActivityExecutionResult> OnExecuteAsync(
           ActivityExecutionContext context)
       {
           var tenantId = TenantContext.GetCurrentTenantId();
           Logger.LogInformation(
               "Executing {ActivityType} for tenant {TenantId}",
               GetType().Name, tenantId);

           try
           {
               return await ExecuteActivityAsync(context);
           }
           catch (Exception ex)
           {
               Logger.LogError(ex,
                   "Activity {ActivityType} failed for tenant {TenantId}",
                   GetType().Name, tenantId);
               return Fault(ex.Message);
           }
       }

       protected abstract Task<ActivityExecutionResult> ExecuteActivityAsync(
           ActivityExecutionContext context);
   }
   ```

6. **Implement State-Specific Activities**:
   ```csharp
   public class CaliforniaProviderBackgroundCheck : StateSpecificActivity
   {
       private readonly IBackgroundCheckService _backgroundCheckService;

       [ActivityInput]
       public ProviderApplication Application { get; set; }

       [ActivityOutput]
       public BackgroundCheckResult Result { get; set; }

       protected override async Task<ActivityExecutionResult> ExecuteActivityAsync(
           ActivityExecutionContext context)
       {
           // California-specific background check logic
           var result = await _backgroundCheckService.CheckProviderAsync(
               Application.ProviderId,
               includeCaliforniaSpecificChecks: true,
               checkFingerprints: true,
               checkChildAbuse: true,
               checkMedicareSanctions: true);

           Result = result;

           return result.Status == BackgroundCheckStatus.Clear
               ? Outcome("Clear")
               : Outcome("Flagged", result.Notes);
       }
   }

   public class TexasLicenseVerification : StateSpecificActivity
   {
       private readonly ITexasLicenseService _licenseService;

       [ActivityInput]
       public string LicenseNumber { get; set; }

       [ActivityInput]
       public string ProviderType { get; set; }

       [ActivityOutput]
       public LicenseVerificationResult VerificationResult { get; set; }

       protected override async Task<ActivityExecutionResult> ExecuteActivityAsync(
           ActivityExecutionContext context)
       {
           // Texas-specific license verification
           var result = await _licenseService.VerifyLicenseAsync(
               LicenseNumber, ProviderType);

           VerificationResult = result;

           if (!result.IsValid)
               return Outcome("Invalid", result.Reason);

           if (result.ExpirationDate < DateTime.Today.AddDays(30))
               return Outcome("Expiring", "License expires within 30 days");

           return Outcome("Valid");
       }
   }
   ```

7. **Create Workflow Activity Repository**:
   ```csharp
   public interface ICustomActivityRegistry
   {
       void RegisterActivity<TActivity>() where TActivity : IActivity;
       IEnumerable<Type> GetRegisteredActivities();
       IActivity CreateActivity(string activityType);
   }

   public class CustomActivityRegistry : ICustomActivityRegistry
   {
       private readonly Dictionary<string, Type> _activities = new();
       private readonly IServiceProvider _serviceProvider;

       public void RegisterActivity<TActivity>() where TActivity : IActivity
       {
           var activityType = typeof(TActivity);
           _activities[activityType.Name] = activityType;
       }

       public IActivity CreateActivity(string activityType)
       {
           if (!_activities.TryGetValue(activityType, out var type))
               throw new InvalidOperationException($"Activity type {activityType} not registered");

           return (IActivity)ActivatorUtilities.CreateInstance(_serviceProvider, type);
       }
   }
   ```

