#### Phase 3: Workflow Designer and Management

8. **Implement Workflow Loading**:
   ```csharp
   public class TenantWorkflowLoader
   {
       private readonly IWorkflowDefinitionStore _workflowStore;

       public async Task<IWorkflow> LoadWorkflowForTenantAsync(
           string workflowName, string tenantId)
       {
           // Load tenant-specific workflow definition
           var definition = await _workflowStore.GetAsync(
               $"{tenantId}_{workflowName}");

           if (definition == null)
           {
               // Fall back to default workflow
               definition = await _workflowStore.GetAsync(workflowName);
           }

           return await _workflowStore.MaterializeAsync(definition);
       }
   }
   ```

9. **Create Workflow Testing Framework**:
   ```csharp
   public class WorkflowTestRunner
   {
       private readonly IWorkflowInvoker _invoker;

       public async Task<WorkflowTestResult> TestWorkflowAsync<TWorkflow>(
           object input,
           Dictionary<string, object> mockActivityResults = null)
           where TWorkflow : IWorkflow
       {
           var workflow = Activator.CreateInstance<TWorkflow>();

           // Replace activities with mocks if provided
           if (mockActivityResults != null)
           {
               foreach (var mock in mockActivityResults)
               {
                   workflow.ReplaceActivity(mock.Key, new MockActivity(mock.Value));
               }
           }

           var result = await _invoker.InvokeAsync(workflow, input);

           return new WorkflowTestResult
           {
               Success = result.Status == WorkflowStatus.Finished,
               Output = result.Output,
               ExecutedActivities = result.ExecutedActivities,
               Duration = result.Duration
           };
       }
   }

   public class MockActivity : Activity
   {
       private readonly object _resultToReturn;

       public MockActivity(object result)
       {
           _resultToReturn = result;
       }

       protected override Task<ActivityExecutionResult> OnExecuteAsync(
           ActivityExecutionContext context)
       {
           context.SetOutput(_resultToReturn);
           return Task.FromResult(Done());
       }
   }
   ```

10. **Implement Workflow Versioning**:
    ```csharp
    public class WorkflowVersion
    {
        public string WorkflowId { get; set; }
        public int Version { get; set; }
        public DateTime PublishedDate { get; set; }
        public bool IsActive { get; set; }
        public string DefinitionJson { get; set; }
    }

    public class WorkflowVersionManager
    {
        private readonly IWorkflowDefinitionStore _store;

        public async Task PublishNewVersionAsync(
            string workflowId, IWorkflow workflow)
        {
            var currentVersion = await _store.GetLatestVersionAsync(workflowId);
            var newVersion = new WorkflowVersion
            {
                WorkflowId = workflowId,
                Version = (currentVersion?.Version ?? 0) + 1,
                PublishedDate = DateTime.UtcNow,
                IsActive = true,
                DefinitionJson = SerializeWorkflow(workflow)
            };

            // Deactivate old version
            if (currentVersion != null)
                currentVersion.IsActive = false;

            await _store.SaveVersionAsync(newVersion);
        }

        public async Task<IWorkflow> GetWorkflowByVersionAsync(
            string workflowId, int version)
        {
            var workflowVersion = await _store.GetVersionAsync(workflowId, version);
            return DeserializeWorkflow(workflowVersion.DefinitionJson);
        }
    }
    ```

