#### Example 3: Workflow with Human Task

```csharp
public class TexasClaimApprovalWorkflow : WorkflowBase
{
    protected override void Build(IWorkflowBuilder builder)
    {
        builder
            .StartWith<ReceiveClaim>()
            .Then<RunClaimEdits>()
            .If(claim => claim.RequiresApproval)
                .Then<CreateApprovalTask>()
                .Then<WaitForApprovalDecision>(task => task
                    .Bookmark = $"approval-{claim.ClaimId}"
                    .Timeout = TimeSpan.FromDays(7))
                .When("Approved")
                    .Then<ProcessApprovedClaim>()
                .When("Denied")
                    .Then<SendDenialNotice>()
                .When("Timeout")
                    .Then<EscalateToSupervisor>()
            .Else()
                .Then<AutoProcessClaim>();
    }
}

// Activity that waits for human decision
public class WaitForApprovalDecision : Activity
{
    public string Bookmark { get; set; }
    public TimeSpan Timeout { get; set; }

    protected override async Task<ActivityExecutionResult> OnExecuteAsync(
        ActivityExecutionContext context)
    {
        // Create bookmark to resume workflow when approval received
        context.CreateScope();
        context.CreateBookmark(Bookmark);

        // Setup timeout
        context.ScheduleActivity<TimeoutActivity>(Timeout);

        return Suspend();
    }

    protected override ActivityExecutionResult OnResume(
        ActivityExecutionContext context)
    {
        var decision = context.GetInput<ApprovalDecision>();
        return Outcome(decision.Status.ToString());
    }
}
```

