### Real-World Example 1: Provider Enrollment Workflow

**Context**: Texas implemented a streamlined 3-step provider enrollment process, while Florida requires a more comprehensive 5-step process with parallel background checks and site inspections.

**Texas Implementation**:

```csharp
public class TexasProviderEnrollmentWorkflow : WorkflowBase
{
    protected override void Build(IWorkflowBuilder builder)
    {
        builder
            .StartWith<ReceiveProviderApplication>(activity =>
            {
                activity.ApplicationTypes = new[] { "Individual", "Group", "Facility" };
            })
            .Then<ValidateTexasLicense>(activity =>
            {
                activity.LicenseTypes = new[]
                {
                    "Medical Doctor",
                    "Registered Nurse",
                    "Licensed Practical Nurse",
                    "Physician Assistant"
                };
                activity.VerificationService = "TexasMedicalBoard";
            })
            .When("Valid")
                .Then<RequestBackgroundCheck>(activity =>
                {
                    activity.CheckTypes = new[]
                    {
                        "CriminalHistory",
                        "ChildAbuseRegistry",
                        "MedicareSanctions"
                    };
                    activity.Vendor = "TexasBackgroundCheckService";
                })
                .Then<WaitForBackgroundCheckCompletion>(activity =>
                {
                    activity.MaxWaitDays = 7;
                    activity.BookmarkName = "texas-background-check-{ProviderId}";
                })
                .When("Clear")
                    .Then<CreateTexasProvider>()
                    .Then<SendApprovalNotification>()
                .When("Flagged")
                    .Then<EscalateToComplianceReview>()
                    .Then<WaitForManualDecision>()
            .When("Invalid")
                .Then<SendLicenseRejectionNotice>();
    }
}
```

**Custom Activity: ValidateTexasLicense**

```csharp
public class ValidateTexasLicense : StateSpecificActivity
{
    private readonly ITexasMedicalBoardService _tmbs;

    [ActivityInput]
    public ProviderApplication Application { get; set; }

    [ActivityInput]
    public string[] LicenseTypes { get; set; }

    [ActivityOutput]
    public LicenseVerificationResult Result { get; set; }

    public ValidateTexasLicense(
        ITexasMedicalBoardService tmbs,
        ITenantContext tenantContext,
        ILogger<ValidateTexasLicense> logger)
        : base(tenantContext, logger)
    {
        _tmbs = tmbs;
    }

    protected override async Task<ActivityExecutionResult> ExecuteActivityAsync(
        ActivityExecutionContext context)
    {
        Logger.LogInformation(
            "Validating Texas license {LicenseNumber} for provider {ProviderId}",
            Application.LicenseNumber, Application.ProviderId);

        // Call Texas Medical Board API
        var verification = await _tmbs.VerifyLicenseAsync(
            Application.LicenseNumber, Application.ProviderType);

        Result = new LicenseVerificationResult
        {
            IsValid = verification.IsActive && verification.NoSanctions,
            LicenseStatus = verification.Status,
            ExpirationDate = verification.ExpirationDate,
            Sanctions = verification.Sanctions
        };

        context.SetOutput(Result);

        if (!Result.IsValid)
        {
            Logger.LogWarning(
                "Texas license validation failed: {Reason}",
                Result.Sanctions.Any() ? "Sanctions present" : "License inactive");
            return Outcome("Invalid", Result.ToString());
        }

        if (Result.ExpirationDate < DateTime.Today.AddDays(90))
        {
            Logger.LogWarning(
                "Texas license expires within 90 days: {ExpirationDate}",
                Result.ExpirationDate);
        }

        return Outcome("Valid");
    }
}
```

