#### Scenario 1: Simple Approval Chain

**Scenario**: California requires director approval for all provider enrollments above a state-defined revenue threshold.

**Implementation**:

```csharp
public class CaliforniaHighValueProviderApproval : WorkflowBase
{
    protected override void Build(IWorkflowBuilder builder)
    {
        builder
            .StartWith<ReceiveProviderApplication>()
            .Then<CalculateProjectedRevenue>()
            .If(app => app.ProjectedRevenue > 2000000)
                .Then<CreateDirectorApprovalTask>(activity =>
                {
                    activity.TaskTitle = "High-Value Provider Approval Required";
                    activity.AssignedRole = "EnrollmentDirector";
                    activity.Priority = TaskPriority.High;
                })
                .Then<WaitForApproval>(activity =>
                {
                    activity.BookmarkName = "director-approval-{ApplicationId}";
                    activity.TimeoutDays = 5;
                })
                .When("Approved")
                    .Then<CompleteEnrollment>()
                    .Then<NotifyApplicant>(outcome => "Approved")
                .When("Denied")
                    .Then<NotifyApplicant>(outcome => "Denied")
                .When("Timeout")
                    .Then<EscalateToChiefMedicalOfficer>()
            .Else()
                .Then<CompleteEnrollment>()
                .Then<NotifyApplicant>(outcome => "Approved");
    }
}
```

**Test Case**:

```csharp
[Fact]
public async Task HighValueProvider_RequiresDirectorApproval()
{
    // Arrange
    var application = new ProviderApplication
    {
        ApplicationId = "CA-APP-001",
        ProviderName = "Large Medical Group",
        ProjectedRevenue = 5000000
    };

    var testRunner = new WorkflowTestRunner(_workflowInvoker);

    // Act - Start workflow
    var result = await testRunner.StartWorkflowAsync<CaliforniaHighValueProviderApproval>(
        application);

    // Assert - Should be suspended waiting for approval
    Assert.Equal(WorkflowStatus.Suspended, result.Status);
    Assert.Contains("director-approval-CA-APP-001", result.Bookmarks);

    // Act - Resume with approval
    result = await testRunner.ResumeWorkflowAsync(
        result.WorkflowInstanceId,
        "director-approval-CA-APP-001",
        new ApprovalDecision { Status = ApprovalStatus.Approved });

    // Assert - Should complete successfully
    Assert.Equal(WorkflowStatus.Finished, result.Status);
    Assert.Contains("CompleteEnrollment", result.ExecutedActivities);
}

[Fact]
public async Task LowValueProvider_AutoApproved()
