**Risk Score Calculation Activity**:

```csharp
public class CalculateProviderRiskScore : StateSpecificActivity
{
    [ActivityInput]
    public CredentialingApplication Application { get; set; }

    [ActivityInput]
    public string[] RiskFactors { get; set; }

    [ActivityOutput]
    public RiskAssessment RiskScore { get; set; }

    protected override async Task<ActivityExecutionResult> ExecuteActivityAsync(
        ActivityExecutionContext context)
    {
        var score = 0;
        var findings = new List<string>();

        // Provider type risk (0-20 points)
        if (Application.ProviderType == "Pharmacy")
        {
            score += 15;
            findings.Add("High-risk provider type: Pharmacy");
        }
        else if (Application.ProviderType == "DME Supplier")
        {
            score += 20;
            findings.Add("High-risk provider type: DME Supplier");
        }

        // Prior sanctions (0-30 points)
        if (Application.PriorSanctions?.Any() == true)
        {
            score += Math.Min(Application.PriorSanctions.Count * 10, 30);
            findings.Add($"Prior sanctions: {Application.PriorSanctions.Count}");
        }

        // Claim history (0-25 points)
        if (Application.PriorClaimDenialRate > 0.30)
        {
            score += 25;
            findings.Add($"High claim denial rate: {Application.PriorClaimDenialRate:P}");
        }
        else if (Application.PriorClaimDenialRate > 0.15)
        {
            score += 15;
            findings.Add($"Elevated claim denial rate: {Application.PriorClaimDenialRate:P}");
        }

        // License status (0-15 points)
        if (Application.LicenseStatus != "Active")
        {
            score += 15;
            findings.Add($"License not active: {Application.LicenseStatus}");
        }

        // Malpractice history (0-10 points)
        if (Application.MalpracticeClaims?.Any() == true)
        {
            score += Math.Min(Application.MalpracticeClaims.Count * 5, 10);
            findings.Add($"Malpractice claims: {Application.MalpracticeClaims.Count}");
        }

        RiskScore = new RiskAssessment
        {
            TotalScore = score,
            RiskLevel = score <= 30 ? "Low" : score <= 70 ? "Medium" : "High",
            Findings = findings
        };

        context.SetOutput(RiskScore);

        Logger.LogInformation(
            "Risk assessment completed: Score={Score}, Level={Level}",
            RiskScore.TotalScore, RiskScore.RiskLevel);

        return Outcome(RiskScore.RiskLevel + "Risk");
    }
}
